import 'dart:io';
import 'package:flutter/material.dart';
import 'package:image_picker/image_picker.dart';
class P extends StatefulWidget{const P({super.key});@override State<P> createState()=>_P();}
class _P extends State<P>{File? f;
  Future<void> pick()async{final r=await ImagePicker().pickImage(source:ImageSource.gallery);if(r!=null)setState(()=>f=File(r.path));}
  @override Widget build(BuildContext c)=>Scaffold(body:Center(child:Column(mainAxisSize:MainAxisSize.min,children:[ElevatedButton(onPressed:pick,child:const Text('Pick')),if(f!=null)Image.file(f!,width:200,height:200)])));}
